foreach ($name in $icons.Keys) {
    $path = $icons[$name]
    # ОРИГИНАЛЬНЫЙ viewBox как в Material Symbols!
    $svgContent = "<svg xmlns=`"http://www.w3.org/2000/svg`" height=`"48px`" viewBox=`"0 -960 960 960`" width=`"48px`" fill=`"#000000`"><path d=`"$path`"/></svg>"
    
    $filePath = ".\assets\icons\$name.svg"
    Set-Content -Path $filePath -Value $svgContent -NoNewline
    
    Write-Host "Restored: $name.svg (original viewBox)" -ForegroundColor Green
}

Write-Host ""
Write-Host "All icons restored with ORIGINAL viewBox!" -ForegroundColor Cyan
Write-Host "Icons will display correctly now!" -ForegroundColor Yellow
